it 'meta ausente não se transforma em zero': {
  const input = baseInput();
  expect(Reflect.deleteProperty(input, 'requiredMarginPercent')).toBe(true);
  expect(input).not.toHaveProperty('requiredMarginPercent');
  const result = calculateFinancialMarginTarget(input, policy);
  if (result.status !== 'unavailable') throw Error('status deve ser unavailable');
  if (result.code !== 'invalid-target') throw Error('code deve ser invalid-target');
  if (result.calculation !== null) throw Error('calculation deve ser null');
  if (result.projection === null || result.projection.status !== 'ready') throw Error('projection deve ser ready');
  expect(result).not.toHaveProperty('value');
  expect(result.projection.netProfit).toEqual(r('510'));
  expect(result.projection.margin).toEqual({ status: 'ready', value: r('51', '100') });
},
it 'limite técnico da meta não se transforma em meta inválida': {
  const result = calculateFinancialMarginTarget({ ...baseInput(), requiredMarginPercent: r('1'.repeat(65)) }, policy);
  if (result.status !== 'unavailable') throw Error('status deve ser unavailable');
  if (result.code !== 'calculation-unavailable') throw Error('code deve ser calculation-unavailable');
  if (result.projection === null || result.projection.status !== 'ready') throw Error('projection deve ser ready');
  if (result.calculation === null) throw Error('calculation deve ser não nulo');
  expect(result).not.toHaveProperty('value');
  expect(result.projection.netProfit).toEqual(r('510'));
  expect(result.projection.margin).toEqual({ status: 'ready', value: r('51', '100') });
}
